import{_ as r,a as o,b as s,c as a,d as n,e}from"./chunks/make-sticker.BPNaJpO6.js";import{_ as p,o as i,c as g,a2 as l}from"./chunks/framework.Bzj1XTnB.js";const f=JSON.parse('{"title":"मूवी, स्टिकर और शेयर करना","description":"MP4, GIF या PNG फ़्रेम एक्सपोर्ट करें, WhatsApp स्टिकर बनाएँ, और पूरे प्रोजेक्ट शेयर करें या उनका बैकअप रखें।","frontmatter":{"lang":"hi","slug":"export-and-share","order":9,"title":"मूवी, स्टिकर और शेयर करना","description":"MP4, GIF या PNG फ़्रेम एक्सपोर्ट करें, WhatsApp स्टिकर बनाएँ, और पूरे प्रोजेक्ट शेयर करें या उनका बैकअप रखें।"},"headers":[],"relativePath":"hi/export-and-share.md","filePath":"hi/export-and-share.md"}'),h={name:"hi/export-and-share.md"};function d(c,t,m,_,u,k){return i(),g("div",null,[...t[0]||(t[0]=[l('<h1 id="मूवी-स्टिकर-और-शेयर-करना" tabindex="-1">मूवी, स्टिकर और शेयर करना <a class="header-anchor" href="#मूवी-स्टिकर-और-शेयर-करना" aria-label="Permalink to &quot;मूवी, स्टिकर और शेयर करना&quot;">​</a></h1><h2 id="मूवी-बनाएँ" tabindex="-1">मूवी बनाएँ <a class="header-anchor" href="#मूवी-बनाएँ" aria-label="Permalink to &quot;मूवी बनाएँ&quot;">​</a></h2><p>एडिटर में ऊपर <strong>गुलाबी शेयर तीर</strong> पर, या <strong>⋮</strong> मेन्यू में <strong>Make movie</strong> पर टैप करें।</p><p><img src="'+r+'" alt="मूवी बनाना"></p><ul><li><p><strong>Movie name</strong></p></li><li><p><strong>Output size</strong> — <strong>Original</strong> (कैनवास का साइज़), <strong>1080p</strong>, <strong>720p</strong>, <strong>480p</strong>, <strong>Square 1080</strong>, <strong>Vertical</strong> (1080 × 1920) या <strong>Custom</strong>।</p></li><li><p><strong>Format</strong>:</p><p><img src="'+o+'" alt="फ़ॉर्मेट"></p><ul><li><strong>MP4</strong> — आवाज़ के साथ वीडियो। YouTube, Instagram, WhatsApp पर शेयर करने के लिए सबसे अच्छा।</li><li><strong>GIF</strong> — चलती हुई तस्वीर। बैकग्राउंड पारदर्शी हो सकता है। <strong>Loop forever</strong> और <strong>Dithering</strong> (रंग ज़्यादा चिकने) चुनें।</li><li><strong>PNG Sequence</strong> — हर फ़्रेम एक तस्वीर, एक zip फ़ाइल में, वीडियो एडिटिंग ऐप के लिए।</li></ul></li><li><p><strong>Transparent background</strong> — सिर्फ़ GIF और PNG में।</p></li><li><p><strong>Watermark</strong> — कोने में छोटा Toonik लोगो। जब तक आप चालू न करें, बंद रहता है।</p></li><li><p><strong>Include audio</strong> — सिर्फ़ MP4 में, जब प्रोजेक्ट में आवाज़ हो।</p></li></ul><p><strong>Make movie</strong> टैप करें। तैयार होने पर <strong>Share</strong> करें, <strong>Save to gallery</strong> करें, या <strong>Done</strong> टैप करें।</p><p><img src="'+s+'" alt="आपकी मूवी तैयार है"></p><p>आपकी मूवी होम स्क्रीन के <strong>Movies</strong> टैब में रहती हैं। किसी पर टैप करके उसे चलाएँ, शेयर करें, गैलरी में सेव करें या डिलीट करें।</p><p><img src="'+a+'" alt="Movies टैब"></p><p><img src="'+n+'" alt="मूवी चलाना"></p><h2 id="whatsapp-स्टिकर-बनाएँ" tabindex="-1">WhatsApp स्टिकर बनाएँ <a class="header-anchor" href="#whatsapp-स्टिकर-बनाएँ" aria-label="Permalink to &quot;WhatsApp स्टिकर बनाएँ&quot;">​</a></h2><p><strong>⋮ → Make sticker</strong> खोलें। आपका एनिमेशन चलता हुआ WhatsApp स्टिकर बन जाता है।</p><p><img src="'+e+'" alt="स्टिकर बनाना"></p><ol><li>तीन तक <strong>Emoji</strong> चुनें — कोई इनमें से कोई इमोजी लिखे तो WhatsApp आपका स्टिकर सुझाता है।</li><li>कोई <strong>Pack</strong> चुनें, या नया शुरू करने के लिए नाम लिखें।</li><li><strong>Make sticker</strong> टैप करें।</li></ol><p>Toonik स्टिकर को आपकी ड्रॉइंग के हिसाब से फ़्रेम करता है, ताकि छोटी सी ड्रॉइंग भी पूरा स्टिकर भर दे। स्टिकर 512 × 512 और 500 KB से छोटे होते हैं, इसलिए लंबे एनिमेशन के कुछ फ़्रेम हट सकते हैं।</p><p><strong>WhatsApp में पैक जोड़ने के लिए उसमें कम से कम 3 स्टिकर चाहिए।</strong> तब तक पैक बताता है कि और कितने चाहिए। तैयार होने पर <strong>Add to WhatsApp</strong> टैप करें। जो पैक पहले से WhatsApp में हैं उन पर <strong>Added</strong> दिखता है; WhatsApp Business भी हो तो <strong>Add to Business</strong> भी कर सकते हैं। एक पैक में 30 स्टिकर तक आते हैं।</p><h2 id="एक-फ़्रेम-शेयर-करें" tabindex="-1">एक फ़्रेम शेयर करें <a class="header-anchor" href="#एक-फ़्रेम-शेयर-करें" aria-label="Permalink to &quot;एक फ़्रेम शेयर करें&quot;">​</a></h2><p>फ़्रेम की पट्टी में किसी फ़्रेम पर लॉन्ग-प्रेस करें और <strong>Share</strong> टैप करें — वह ड्रॉइंग तस्वीर के रूप में जाती है।</p><h2 id="पूरा-प्रोजेक्ट-शेयर-करें-या-बैकअप-रखें" tabindex="-1">पूरा प्रोजेक्ट शेयर करें या बैकअप रखें <a class="header-anchor" href="#पूरा-प्रोजेक्ट-शेयर-करें-या-बैकअप-रखें" aria-label="Permalink to &quot;पूरा प्रोजेक्ट शेयर करें या बैकअप रखें&quot;">​</a></h2><p>होम स्क्रीन पर किसी प्रोजेक्ट पर लॉन्ग-प्रेस करें और <strong>Export project</strong> टैप करें। आपको <code>.flippa</code> फ़ाइल मिलती है: दोस्त को भेजें, बैकअप रखें, या दूसरे फ़ोन पर <strong>⋮ → Import project</strong> से खोलें।</p>',20)])])}const x=p(h,[["render",d]]);export{f as __pageData,x as default};
